 ARMReg ARMXEmitter::SubBase(ARMReg Reg)
 {
 	if (Reg >= S0)
 	{
 		if (Reg >= D0)
 		{
 			if (Reg >= Q0)
 				return (ARMReg)((Reg - Q0) * 2); // Always gets encoded as a double register
 			return (ARMReg)(Reg - D0);
 		}
 		return (ARMReg)(Reg - S0);
 	}
 	return Reg;
 }

