+			Memory::Write_U64(0,curFileInfoAddr + 48); // TODO mtime
+			Memory::Write_U64(0,curFileInfoAddr + 56); // TODO unknow
+			foundFiles++;
+		}
+	}
+
+	// TODO : verify if return true if at least 1 file found or only if all found
+	return foundFiles > 0;
