+void Jit::Comp_VPFX(u32 op)
+{
+	int data = op & 0xFFFFF;
+	int regnum = (op >> 24) & 3;
+	switch (regnum) {
+	case 0:  // S
+		js.prefixS = data;
+		js.prefixSKnown = true;
+		break;
+	case 1:  // T
+		js.prefixT = data;
+		js.prefixTKnown = true;
+		break;
+	case 2:  // D
+		js.prefixD = data;
+		js.prefixDKnown = true;
+		break;
+	}
+	// TODO: Defer this to end of block
+	MOV(32, M((void *)&mips_->vfpuCtrl[VFPU_CTRL_SPREFIX + regnum]), Imm32(data));
+}
