S operator/(const S &i, const swap_struct_t<T, F>& v) {
	return i / v.swap();
}

template <typename S, typename T, typename F>
S operator*(const S &i, const swap_struct_t<T, F>& v) {
	return i * v.swap();
}

template <typename S, typename T, typename F>
S operator%(const S &i, const swap_struct_t<T, F>& v) {
	return i % v.swap();
}

// Arithmetics + assignements
template <typename S, typename T, typename F>
S &operator+=(S &i, const swap_struct_t<T, F>& v) {
	i += v.swap();
	return i;
}

template <typename S, typename T, typename F>
S &operator-=(S &i, const swap_struct_t<T, F>& v) {
	i -= v.swap();
	return i;
}

// Logical
template <typename S, typename T, typename F>
S operator&(const S &i, const swap_struct_t<T, F>& v) {
	return i & v.swap();
}

template <typename S, typename T, typename F>
S operator&(const swap_struct_t<T, F>& v, const S &i) {
	return (S)(v.swap() & i);
}


