+void IniFile::Section::Set(const char* key, const std::vector<std::string>& newValues) 
+{
+	std::string temp;
+	// Join the strings with , 
+	std::vector<std::string>::const_iterator it;
+	for (it = newValues.begin(); it != newValues.end(); ++it)
+	{
+		temp += (*it) + ",";
+	}
+	// remove last ,
