+void ElfReader::LoadRelocations2(int rel_seg)
+{
+	Elf32_Phdr *ph;
+	u8 *buf, *end, *flag_table, *type_table;
+	int flag_table_size, type_table_size;
+	int flag_bits, seg_bits, type_bits;
