static bool blendColorSimilar(Vec3f a, Vec3f b, float margin = 0.1f) {
	Vec3f diff = a - b;
	if (fabsf(diff.x) <= margin && fabsf(diff.y) <= margin && fabsf(diff.z) <= margin)
		return true;
	return false;
}

