 	// Invert 0x80000000 -> 0x7FFFFFFF for the NAN result.
 	fp_.MVNI(32, EncodeRegToDouble(SCRATCHF1), 0x80, 24);
 	fp_.FCMP(regs_.F(inst.src1), regs_.F(inst.src1));

