 template <typename T>
 inline void AttachFramebufferInvalid(T &entry, VirtualFramebuffer *framebuffer) {
 	if (entry->framebuffer == 0 || entry->framebuffer == framebuffer) {
 		entry->framebuffer = framebuffer;
 		entry->invalidHint = -1;
 	}
