+static void SwapUVs(GPUDebugVertex &a, GPUDebugVertex &b) {
+	float tempu = a.u;
+	float tempv = a.v;
+	a.u = b.u;
+	a.v = b.v;
+	b.u = tempu;
+	b.v = tempv;
+}
+
+static void RotateUVThrough(GPUDebugVertex v[4]) {
+	float x1 = v[2].x;
+	float x2 = v[0].x;
+	float y1 = v[2].y;
+	float y2 = v[0].y;
+
+	if ((x1 < x2 && y1 > y2) || (x1 > x2 && y1 < y2))
+		SwapUVs(v[1], v[3]);
+}
+
+static void ExpandRectangles(std::vector<GPUDebugVertex> &vertices, std::vector<u16> &indices, int &count, bool throughMode) {
+	static std::vector<GPUDebugVertex> newVerts;
+	static std::vector<u16> newInds;
+
+	if (indices.empty()) {
+		// Ugh, let's just go the easy way.
+		indices.resize(count);
+		for (int i = 0; i < count; ++i) {
+			indices[i] = i;
+		}
+	}
+
+	newVerts.resize(indices.size() * 2);
+	newInds.resize(indices.size() * 3);
+
+	u16 v = 0;
+	GPUDebugVertex *vert = &newVerts[0];
+	u16 *ind = &newInds[0];
+	for (size_t i = 0, end = indices.size(); i < end; i += 2) {
+		const auto &orig_tl = vertices[indices[i]];
+		const auto &orig_br = vertices[indices[i + 1]];
+
+		vert[0] = orig_br;
+
+		// Top right.
+		vert[1] = orig_br;
+		vert[1].y = orig_tl.y;
+		vert[1].v = orig_tl.v;
+
+		vert[2] = orig_tl;
+
+		// Bottom left.
+		vert[3] = orig_br;
+		vert[3].x = orig_tl.x;
+		vert[3].u = orig_tl.u;
+
+		// That's the four corners. Now process UV rotation.
+		if (throughMode)
+			RotateUVThrough(vert);
+
+		// Build the two 3 point triangles from our 4 coordinates.
+		*ind++ = v + 0;
+		*ind++ = v + 1;
+		*ind++ = v + 2;
+		*ind++ = v + 3;
+		*ind++ = v + 0;
+		*ind++ = v + 2;
+
+		vert += 4;
+		v += 4;
+	}
+
+	std::swap(vertices, newVerts);
+	std::swap(indices, newInds);
+	count *= 3;
+}

