 std::string ISOFileSystem::EntryFullPath(TreeEntry *e) {
 	if (e == &entireISO)
 		return "";

 	size_t fullLen = 0;
 	TreeEntry *cur = e;
 	while (cur != NULL && cur != treeroot) {
 		// For the "/".
 		fullLen += 1 + cur->name.size();
 		cur = cur->parent;
 	}

 	std::string path;
 	path.resize(fullLen);

 	cur = e;
 	while (cur != NULL && cur != treeroot) {
 		path.replace(fullLen - cur->name.size(), cur->name.size(), cur->name);
 		path.replace(fullLen - cur->name.size() - 1, 1, "/");
 		fullLen -= 1 + cur->name.size();
 		cur = cur->parent;
 	}

 	return path;
 }

