 			Decimate();
 			// Try again.
 			glTexImage2D(GL_TEXTURE_2D, level, components, w, h, 0, components, dstFmt, pixelData);
 		}
 	}

 	if (useUnpack) {
 		glPixelStorei(GL_UNPACK_ROW_LENGTH, 0);
 	}
 }

