bool parseNumber(char *str, int defaultrad, int len, uint32_t &result) {
	int val = 0;
	int r = 0;
	if (len == 0)
		len = (int)strlen(str);

	if (str[0] == '0' && radixFromZeroPrefix(str[1]) != -1) {
		r = radixFromZeroPrefix(str[1]);
		str += 2;
		len -= 2;
	} else if (str[0] == '$') {
		r = 16;
		str++;
		len--;
	} else if (str[0] >= '0' && str[0] <= '9') {
		int suffix = radixFromSuffix(str[len - 1], defaultrad);
		if (suffix != -1) {
			r = suffix;
			len--;
		} else {
			r = defaultrad;
		}
	} else {
		return false;
	}

	switch (r)
	{
	case 2: // bin
		while (len--)
		{
			if (*str != '0' && *str != '1') return false;
			val = val << 1;
			if (*str++ == '1')
			{
				val++;
			}
		}
		break;
	case 8: // oct
		while (len--)
		{
			if (*str < '0' || *str > '7') return false;
			val = val << 3;
			val+=(*str++-'0');
		}
		break;
	case 10: // dec
		while (len--)
		{
			if (*str < '0' || *str > '9') return false;
			val = val * 10;
			val += (*str++ - '0');
		}
		break;
	case 16: // hex
		while (len--)
		{
			char c = tolower(*str++);
			if ((c < '0' || c > '9') && (c < 'a' || c > 'f')) return false;
			val = val << 4;

			if (c >= 'a') val += c-'a'+10;
			else val += c-'0';
		}
		break;
	default:
		return false;
	}

	result = val;
	return true;
}

