		switch (ptr->ai_family) {
		case AF_INET:
			serverIp = ((sockaddr_in *)ptr->ai_addr)->sin_addr;
			break;
		}
	}

	freeaddrinfo(resultAddr);

	// If Server is at localhost Try to Bind socket to specific adapter before connecting to prevent 2nd instance being recognized as already existing 127.0.0.1 by AdhocServer
	// (may not works in WinXP/2003 for IPv4 due to "Weak End System" model)
	if (((uint8_t*)&serverIp.s_addr)[0] == 0x7f) { // (serverIp.S_un.S_un_b.s_b1 == 0x7f) 
		int on = 1;
		setsockopt(metasocket, SOL_SOCKET, SO_REUSEADDR, (const char*)&on, sizeof(on));
		setsockopt(metasocket, SOL_SOCKET, SO_DONTROUTE, (const char*)&on, sizeof(on));

		((struct sockaddr_in*) & localIP)->sin_port = 0;
		// Bind Local Address to Socket
		iResult = bind(metasocket, (struct sockaddr*) & localIP, sizeof(sockaddr));
		if (iResult == SOCKET_ERROR) {
			ERROR_LOG(SCENET, "Bind to alternate localhost[%s] failed(%i).", inet_ntoa(((struct sockaddr_in*) & localIP)->sin_addr), iResult);
		}
	}

	memset(&parameter, 0, sizeof(parameter));
	strcpy((char *)&parameter.nickname.data, g_Config.sNickName.c_str());
	parameter.channel = 1; // Fake Channel 1
	getLocalMac(&parameter.bssid.mac_addr);

	server_addr.sin_addr = serverIp;
	iResult = connect(metasocket,(sockaddr *)&server_addr,sizeof(server_addr));
	if (iResult == SOCKET_ERROR) {
		uint8_t * sip = (uint8_t *)&server_addr.sin_addr.s_addr;
		char buffer[512];
		snprintf(buffer, sizeof(buffer), "Socket error (%i) when connecting to %s/%u.%u.%u.%u:%u", errno, g_Config.proAdhocServer.c_str(), sip[0], sip[1], sip[2], sip[3], ntohs(server_addr.sin_port));
		ERROR_LOG(SCENET, "%s", buffer);
		host->NotifyUserMessage(buffer, 8.0f);
		return iResult;
	}
	//grab local ip for later use better than constant ip on non windows platform
	localip = getLocalIp(metasocket);

	// Prepare Login Packet
	SceNetAdhocctlLoginPacketC2S packet;
	packet.base.opcode = OPCODE_LOGIN;
	SceNetEtherAddr addres;
	getLocalMac(&addres);
	packet.mac = addres;
	strcpy((char *)packet.name.data, g_Config.sNickName.c_str());
	memcpy(packet.game.data, adhoc_id->data, ADHOCCTL_ADHOCID_LEN);
	int sent = send(metasocket, (char*)&packet, sizeof(packet), 0);
	changeBlockingMode(metasocket, 1); // Change to non-blocking
	if (sent > 0) {
		auto n = GetI18NCategory("Networking");
		host->NotifyUserMessage(n->T("Network Initialized"), 1.0);
		return 0;
	}
	else{
		return -1;
	}
}

bool resolveIP(uint32_t ip, SceNetEtherAddr * mac) {
	sockaddr_in addr;
	getLocalIp(&addr);
	uint32_t localIp = addr.sin_addr.s_addr;

	if (ip == localIp || ip == ((sockaddr_in*)&localIP)->sin_addr.s_addr){
		getLocalMac(mac);
		return true;
	}

	// Multithreading Lock
	peerlock.lock();

	// Peer Reference
	SceNetAdhocctlPeerInfo * peer = friends;

	// Iterate Peers
	for (; peer != NULL; peer = peer->next) {
		// Found Matching Peer
		if (peer->ip_addr == ip) {
			// Copy Data
			*mac = peer->mac_addr;

			// Multithreading Unlock
			peerlock.unlock();

			// Return Success
			return true;
		}
	}

	// Multithreading Unlock
	peerlock.unlock();

	// Peer not found
	return false;
}

