 		if (g_Config.iAltSpeedVolume != -1) {
 			volume = g_Config.iAltSpeedVolume;
 		}
 	}

 	if (volume >= VOLUME_MAX) {
 		ClampBufferToS16<false>(out, in, size, 0);
 	} else if (volume <= VOLUME_OFF) {
 		memset(out, 0, size * sizeof(s16));
