 bool RefCountedObject::Release() {
 	if (refcount_ > 0 && refcount_ < 10000) {
 		if (--refcount_ == 0) {
 			// Make it very obvious if we try to free this again.
 			refcount_ = 0xDEDEDE;
 			delete this;
 			return true;
 		}
 	} else {
 		_dbg_assert_msg_(false, "Refcount (%d) invalid for object %p - corrupt?", refcount_.load(), this);
 	}
 	return false;
 }


