+	VirtualFramebuffer *src = framebufferManager_->GetVFBAt(clutRenderAddress_);
+	if (!src) {
+		// What do we do?
+		return;
+	}
+
+	Draw::Framebuffer *clutFbo = dynamicClutFbo_;
+
