 		vrCompat[VR_COMPAT_FBO_CLEAR] = true;
 	}

 	// Remove original sky plane.
 	bool depthEnabled = false;
 	for (auto& command : step->commands) {
 		if (command.cmd == GLRRenderCommand::DEPTH) {
